import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    lines = raw_csv.splitlines(keepends=True)
    start = 0

    # Skip blank lines and comment-style preambles before the first CSV record.
    while start < len(lines):
        stripped = lines[start].lstrip("\ufeff \t")
        if not stripped.strip() or stripped.startswith("#"):
            start += 1
            continue
        break

    if start == len(lines):
        return {"columns": [], "rows": []}

    reader = csv.reader(
        io.StringIO("".join(lines[start:]), newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )

    records = []
    for record in reader:
        if not record or all(not value.strip() for value in record):
            continue
        records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    columns = [value.lstrip("\ufeff").strip() for value in records[0]]
    width = len(columns)
    rows = []

    for record in records[1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            record = record[:width]
        rows.append(record)

    return {"columns": columns, "rows": rows}
